import json, glob
kinds = {}
examples = {}
for path in sorted(glob.glob('data/*.jsonl')):
    for line in open(path):
        rec = json.loads(line)
        k = rec.get('kind')
        kinds[k] = kinds.get(k, 0) + 1
        if k == 'span' and examples.get('span') is None:
            examples['span'] = rec
        if k == 'log' and examples.get('log') is None:
            examples['log'] = rec
print("kinds:", kinds)
print("span keys:", list(examples['span'].keys()))
print("span body.span keys:", list(examples['span'].get('body', {}).get('span', {}).keys()))
# edge cases: no elapsed spans
noel = 0
for path in sorted(glob.glob('data/*.jsonl')):
    for line in open(path):
        rec = json.loads(line)
        if rec.get('kind') == 'span' and rec.get('body', {}).get('span', {}).get('elapsed') is None:
            noel += 1
print("spans with no elapsed:", noel)
EOF
